package com.learnknow.ai;
import jakarta.persistence.*;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.SpringBootApplication;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.web.bind.annotation.*;import java.time.Instant;
@SpringBootApplication public class AiServiceApplication{public static void main(String[]a){SpringApplication.run(AiServiceApplication.class,a);}@Entity public static class AIInteraction{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)public Long id;public Long userId;@Column(columnDefinition="TEXT")public String question;@Column(columnDefinition="TEXT")public String response;public Instant timestamp=Instant.now();}@org.springframework.stereotype.Repository public interface Repo extends JpaRepository<AIInteraction,Long>{}public record AskRequest(Long userId,String question){}public record AskResponse(Long id,String response,Instant timestamp){}@RestController @RequestMapping("/api/ai")public static class Controller{final InteractionRepository repo;Controller(InteractionRepository r){repo=r;}@PostMapping("/ask")AskResponse ask(@RequestBody AskRequest r){String q=r.question()==null?"":r.question().toLowerCase();String answer;if(q.contains("nullpointer"))answer="A NullPointerException occurs when Java code uses a null reference. Check the object before calling a method or field, and use a debugger to find where it became null.";else if(q.contains("recursion"))answer="Recursion is when a method calls itself. Define a clear base case and make each call move toward it to avoid infinite recursion.";else if(q.contains("rest")||q.contains("api"))answer="A REST API exposes resources over HTTP. Use nouns in URLs, HTTP methods for actions, status codes for results, and JSON for representations.";else if(q.contains("exception"))answer="Exceptions represent abnormal program conditions. Handle only cases you can recover from and preserve the original cause when rethrowing.";else answer="Break the problem into inputs, expected output, and small testable steps. In Java, inspect the stack trace, verify types and boundaries, then write a focused test.";AIInteraction x=new AIInteraction();x.userId=r.userId();x.question=r.question();x.response=answer;x=repo.save(x);return new AskResponse(x.id,x.response,x.timestamp);}}}
